/* From Uiverse.io by Yaya12085 - Tags: icon, button, hover, dark, download, google */
.__UIV_SCOPE__ .playstore-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 2px solid #000;
  border-radius: 9999px;
  background-color: rgba(0, 0, 0, 1);
  padding: 0.625rem 1.5rem;
  text-align: center;
  color: rgba(255, 255, 255, 1);
  outline: 0;
  transition: all  .2s ease;
  text-decoration: none;
}

.__UIV_SCOPE__ .playstore-button:hover {
  background-color: transparent;
  color: rgba(0, 0, 0, 1);
}

.__UIV_SCOPE__ .icon {
  height: 1.5rem;
  width: 1.5rem;
}

.__UIV_SCOPE__ .texts {
  margin-left: 1rem;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  line-height: 1;
}

.__UIV_SCOPE__ .text-1 {
  margin-bottom: 0.25rem;
  font-size: 0.75rem;
  line-height: 1rem;
}

.__UIV_SCOPE__ .text-2 {
  font-weight: 600;
}
